365: /* ───────────────────────── EVENTOS / HISTORIAL ───────────────────────── */
366: function clockText() {
367:   if (!state) return '--:--';
368:   const mins = (WORKDAY_START * 60 + state.dayTime * WORKDAY_HOURS * 60) % (24 * 60);
369:   return `${String(Math.floor(mins / 60)).padStart(2, '0')}:${String(Math.floor(mins % 60)).padStart(2, '0')}`;
