371: function logEvent(category, text, amount) {
372:   if (!state) return;
373:   if (!Array.isArray(state.events)) state.events = [];
374:   state.events.unshift({
375:     id: 'e' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5),
376:     day: state.day, time: clockText(), category,
377:     text, amount: Number.isFinite(amount) ? amount : null,
378:   });
379:   if (state.events.length > 260) state.events.length = 260;
380: }
381: function snapshotCash() {
382:   if (!state) return;
383:   if (!state.history) state.history = { cash: [], harvests: [] };
384:   const arr = state.history.cash;
385:   const last = arr[arr.length - 1];
386:   const val = Math.round(state.cash);
387:   if (!last || last.day !== state.day) arr.push({ day: state.day, value: val });
388:   else last.value = val;
389:   if (arr.length > 180) arr.shift();
390: }
391: function addHarvestHistory(kg, cropId) {
392:   if (!state) return;
393:   if (!state.history) state.history = { cash: [], harvests: [] };
394:   state.history.harvests.push({ day: state.day, kg: +kg.toFixed(2), cropId });
395:   if (state.history.harvests.length > 240) state.history.harvests.shift();
396: }
