518: /* ───────────────────────── ECONOMY ───────────────────────── */
519: function changeCash(amount) {
520:   state.cash += amount;
521:   updateHUD();
522:   flashCash(amount >= 0 ? 1 : -1);
523: }
524: function flashCash(dir) {
525:   if (!D.cashBlock) return;
526:   D.cashBlock.classList.remove('flash-up', 'flash-down');
527:   void D.cashBlock.offsetWidth;
528:   D.cashBlock.classList.add(dir > 0 ? 'flash-up' : 'flash-down');
529:   clearTimeout(flashCash._t);
530:   flashCash._t = setTimeout(() => D.cashBlock.classList.remove('flash-up', 'flash-down'), 500);
531: }
532: function sellCrop(cropId, kg) {
533:   const stock = state.inventory[cropId] || 0;
534:   kg = Math.min(kg, stock);
535:   if (kg < 0.01) return;
536:   const crop = cropById(cropId);
537:   const price = sellPrice(cropId, state);
538:   const revenue = kg * price;
539:   state.inventory[cropId] = +(stock - kg).toFixed(2);
540:   state.cash += revenue;
541:   state.stats.revenue += revenue;
542:   toast(`💵 Vendiste ${fmtNum(kg)} kg de ${crop.name} por <strong>${fmtMoney(revenue)}</strong> a ${fmtMoney(price)}/kg.`, 'money');
543:   logEvent('money', `Venta de ${fmtNum(kg)} kg de ${crop.name} a ${fmtMoney(price)}/kg.`, revenue);
544:   snapshotCash();
545:   updateHUD();
546:   flashCash(1);
547:   Sfx.play('sell');
548:   checkGoals();
549:   saveGame(true);
550: }
551: function sellAll() {
552:   let total = 0, kg = 0;
553:   for (const crop of CROPS) {
554:     const stock = state.inventory[crop.id] || 0;
555:     if (stock < 0.01) continue;
556:     const price = sellPrice(crop.id, state);
557:     total += stock * price; kg += stock;
558:     state.inventory[crop.id] = 0;
559:   }
560:   if (kg < 0.01) { toast('Todavía no hay nada en el depósito para vender.', 'warn'); Sfx.play('error'); return; }
561:   state.cash += total;
562:   state.stats.revenue += total;
563:   toast(`💵 Vendiste ${fmtNum(kg)} kg de producción por <strong>${fmtMoney(total)}</strong>.`, 'money');
564:   logEvent('money', `Venta total de ${fmtNum(kg)} kg de producción.`, total);
565:   snapshotCash();
566:   updateHUD(); flashCash(1); Sfx.play('sell');
567:   checkGoals(); saveGame(true);
568: }
