570: /* ───────────────────────── CONTRACTS ───────────────────────── */
571: function offerContract() {
572:   const crop = CROPS[Math.floor(Math.random() * CROPS.length)];
573:   const qty = Math.max(1, Math.round((1.5 + Math.random() * 6) * (crop.yieldKg / 1.4) * 2) / 2);
574:   const repFactor = 0.85 + state.reputation * 0.06;
575:   const reward = Math.round(qty * crop.basePrice * (1.3 + Math.random() * 0.25) * repFactor);
576:   state.contracts.offers.push({
577:     id: 'o' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5),
578:     cropId: crop.id, qty, reward,
579:     deadline: state.day + 3 + Math.floor(Math.random() * 3),
580:     expires: state.day + 2,
581:   });
582: }
583: function acceptOffer(id) {
584:   const idx = state.contracts.offers.findIndex(o => o.id === id);
585:   if (idx < 0) return;
586:   const offer = state.contracts.offers.splice(idx, 1)[0];
587:   state.contracts.active.push(offer);
588:   toast(`📋 Pedido aceptado: ${offer.qty} kg de ${cropById(offer.cropId).name} para el día ${offer.deadline}.`, 'money');
589:   logEvent('money', `Pedido aceptado: ${offer.qty} kg de ${cropById(offer.cropId).name} para el día ${offer.deadline}.`);
590:   Sfx.play('click');
591:   renderContracts(); updateHUD(); saveGame(true);
592: }
593: function declineOffer(id) {
594:   state.contracts.offers = state.contracts.offers.filter(o => o.id !== id);
595:   Sfx.play('click'); renderContracts(); updateHUD(); saveGame(true);
596: }
597: function deliverContract(id) {
598:   const c = state.contracts.active.find(o => o.id === id);
599:   if (!c) return;
600:   const crop = cropById(c.cropId);
601:   if ((state.inventory[c.cropId] || 0) < c.qty - 0.001) {
602:     toast(`No alcanza ${crop.name}: tenés ${fmtNum(state.inventory[c.cropId] || 0)} de ${c.qty} kg.`, 'warn');
603:     Sfx.play('error'); return;
604:   }
605:   state.inventory[c.cropId] = +(state.inventory[c.cropId] - c.qty).toFixed(2);
606:   state.cash += c.reward;
607:   state.stats.revenue += c.reward;
608:   state.stats.contractsDelivered++;
609:   state.reputation = clamp(state.reputation + 0.18 + (state.upgrades.marketing || 0) * 0.02, 1, 5);
610:   state.contracts.active = state.contracts.active.filter(o => o.id !== id);
611:   toast(`🤝 Entregaste ${c.qty} kg de ${crop.name} — <strong>${fmtMoney(c.reward)}</strong> y reputación.`, 'money');
612:   logEvent('money', `Pedido entregado: ${c.qty} kg de ${crop.name}.`, c.reward);
613:   snapshotCash();
614:   Sfx.play('fanfare'); updateHUD(); flashCash(1);
615:   checkGoals(); renderContracts(); saveGame(true);
616: }
617: function expireContracts() {
618:   const failed = state.contracts.active.filter(c => state.day > c.deadline);
619:   if (failed.length) {
620:     for (const c of failed) {
621:       state.reputation = clamp(state.reputation - 0.3, 1, 5);
622:       toast(`❌ Pedido vencido: ${c.qty} kg de ${cropById(c.cropId).name}. Te bajó la reputación.`, 'bad');
623:       logEvent('money', `Pedido vencido: ${c.qty} kg de ${cropById(c.cropId).name}. Reputación −0,3.`);
624:     }
625:     state.contracts.active = state.contracts.active.filter(c => state.day <= c.deadline);
626:   }
627:   state.contracts.offers = state.contracts.offers.filter(o => state.day <= o.expires);
628: }
