630: /* ───────────────────────── UPGRADES ───────────────────────── */
631: function upgradeLevel(id) {
632:   const u = UPGRADES.find(x => x.id === id);
633:   if (u.maxLevel === 1) return state.upgrades[id] ? 1 : 0;
634:   return state.upgrades[id] || 0;
635: }
636: function upgradeCost(id) {
637:   const u = UPGRADES.find(x => x.id === id);
638:   const lvl = upgradeLevel(id);
639:   return lvl >= u.maxLevel ? null : u.costs[lvl];
640: }
641: function buyUpgrade(id) {
642:   const u = UPGRADES.find(x => x.id === id);
643:   const cost = upgradeCost(id);
644:   if (cost == null) return;
645:   if (state.cash < cost) { toast('No te alcanza la plata para esa mejora.', 'bad'); Sfx.play('error'); return; }
646:   state.cash -= cost;
