684: function snap(v) { return Math.round(v * 2) / 2; }
685: function bedHalf(type) {
686:   const sz = (BED_TYPES[type] && BED_TYPES[type].size) || { w: 2.4, d: 1.3 };
687:   return { w: sz.w / 2, d: sz.d / 2 };
