758: function plantCrop(bedId, cropId) {
759:   const bed = state.beds.find(b => b.id === bedId);
760:   const crop = cropById(cropId);
761:   if (!bed || !crop) return;
762:   if (!BED_TYPES[bed.type].crops.includes(cropId)) return;
763:   if (!state.godMode && state.cash < crop.seedCost) { toast(`Necesitás ${fmtMoney(crop.seedCost)} para semillas de ${crop.name}.`, 'bad'); Sfx.play('error'); return; }
764:   if (!state.godMode) state.cash -= crop.seedCost;
765:   bed.cropId = cropId;
766:   bed.growth = 0.02;
767:   bed.health = 100;
768:   bed.ph = 6.1;
769:   bed.ec = (crop.ec[0] + crop.ec[1]) / 2;
770:   bed.plantedDay = state.day;
771:   bed.taskDone = {};
772:   state.stats.planted++;
773:   const rec = state.stats.bySystem[bed.type];
774:   if (rec) rec.seedCost += crop.seedCost;
775:   toast(`🌱 Plantaste ${crop.name}. Ciclo de ${crop.cycleWeeks} semanas: mirá las tareas semanales de la cama.`, 'money');
776:   logEvent('crop', `Siembra de ${crop.name} en ${BED_TYPES[bed.type].name} · cosecha estimada día ${state.day + Math.ceil(crop.growDays / BED_TYPES[bed.type].spec.growth)}.`, -crop.seedCost);
777:   Sfx.play('plant'); flashCash(-1);
