780: function harvestBed(bedId) {
781:   const bed = state.beds.find(b => b.id === bedId);
782:   if (!bed || !bed.cropId || bed.growth < 0.995) return;
783:   const crop = cropById(bed.cropId);
784:   const kg = estHarvestKg(bed);
785:   state.inventory[crop.id] = +((state.inventory[crop.id] || 0) + kg).toFixed(2);
786:   state.stats.harvests++;
787:   state.stats.kgHarvested = +(state.stats.kgHarvested + kg).toFixed(2);
788:   const rec = state.stats.bySystem[bed.type];
789:   if (rec) { rec.harvests++; rec.kg = +(rec.kg + kg).toFixed(2); rec.revenue += kg * sellPrice(crop.id, state); }
790:   toast(`🧺 Cosechaste <strong>${fmtNum(kg)} kg de ${crop.name}</strong>. Ventala en el Mercado.`, 'money');
791:   logEvent('crop', `Cosecha de ${fmtNum(kg)} kg de ${crop.name} en ${BED_TYPES[bed.type].name}.`);
792:   addHarvestHistory(kg, crop.id);
793:   Sfx.play('harvest');
794:   popupAtBed(bed, `+${fmtNum(kg)} kg ${crop.icon}`, 'good');
795:   bed.cropId = null; bed.growth = 0; bed.health = 100; bed.plantedDay = null; bed.taskDone = {};
