807: function doseBed(bedId, kind) {
808:   const bed = state.beds.find(b => b.id === bedId);
809:   if (!bed || !bed.cropId) return;
810:   if (state.upgrades.autoDoser && bed.type !== 'kratky') { toast('El Auto-Dosificador ya se encarga.', 'warn'); return; }
811:   let cost = 0;
812:   if (kind === 'water') { cost = state.upgrades.rain ? 1 : 3; if (bed.water >= maxWater()) { toast('El tanque ya está lleno.', 'warn'); return; } bed.water = maxWater(); }
813:   if (kind === 'ec') { cost = 2; bed.ec = Math.min(3.6, bed.ec + 0.4); }
814:   if (kind === 'phdown') { cost = 1; bed.ph = Math.max(4.5, bed.ph - 0.4); }
815:   if (kind === 'phup') { cost = 1; bed.ph = Math.min(8, bed.ph + 0.4); }
816:   if (!state.godMode && state.cash < cost) { toast('No te alcanza la plata para dosificar.', 'bad'); Sfx.play('error'); return; }
817:   if (!state.godMode) state.cash -= cost;
818:   if (kind === 'water') autoCompleteTask(bed, 'topup');
819:   if (kind === 'ec' || kind === 'phdown' || kind === 'phup') autoCompleteTask(bed, 'test');
820:   Sfx.play('click'); flashCash(-1);
821:   updateHUD(); renderBedPanel(true); saveGame(true);
822: }
